const sharedSecret = $env.N8N_SHARED_SECRET || 'replace-with-a-long-random-secret';
const request = items[0].json;
const headers = Object.fromEntries(
  Object.entries(request.headers ?? {}).map(([key, value]) => [String(key).toLowerCase(), Array.isArray(value) ? value[0] : value]),
);
const receivedSecret = headers['x-aihub-secret'];

if (receivedSecret !== sharedSecret) {
  throw new Error('Unauthorized n8n request');
}

const body = request.body ?? {};
if (!body.executionId || !body.agentId || !body.transactionId || body.paymentVerified !== true) {
  throw new Error('Invalid backend request');
}

const input = body.input ?? {};
const resumeFile = input.resumeFile ?? null;

if (!resumeFile || !resumeFile.data) {
  return [
    {
      json: {
        success: false,
        executionId: body.executionId,
        error: {
          code: 'RESUME_FILE_MISSING',
          message: 'Resume file is missing from the request payload',
        },
      },
    },
  ];
}

const fileName = String(resumeFile.name ?? 'resume');
const fileType = String(resumeFile.type ?? 'application/octet-stream').toLowerCase();
const raw = Buffer.from(String(resumeFile.data), 'base64');

let text = '';
if (fileType.includes('pdf') || fileName.toLowerCase().endsWith('.pdf')) {
  text = raw
    .toString('latin1')
    .replace(/[\u0000-\u001f]+/g, ' ')
    .replace(/[^\x09\x0a\x0d\x20-\x7E]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
} else {
  text = new TextDecoder('utf-8', { fatal: false }).decode(raw).replace(/\s+/g, ' ').trim();
}

if (text.length < 30) {
  return [
    {
      json: {
        success: false,
        executionId: body.executionId,
        error: {
          code: 'RESUME_PARSE_FAILED',
          message: 'Unable to extract enough text from the uploaded resume',
        },
      },
    },
  ];
}

const keywordGroups = [
  'javascript', 'typescript', 'react', 'next.js', 'node.js', 'express', 'mongodb', 'sql',
  'python', 'java', 'aws', 'docker', 'kubernetes', 'git', 'ci/cd', 'testing', 'api',
  'communication', 'leadership', 'problem solving', 'project management', 'agile', 'data analysis',
];

const textLower = text.toLowerCase();
const presentSkills = keywordGroups.filter(item => textLower.includes(item));
const missingSkills = keywordGroups.filter(item => !presentSkills.includes(item));

const hasNumbers = /\b\d{1,3}%\b/.test(text) || /\b\d{1,4}\b/.test(text);
const hasEducation = /\b(bachelor|master|phd|degree|university|college|b\.tech|m\.tech)\b/i.test(text);
const hasActionWords = /\b(improved|built|led|delivered|reduced|increased|optimized|managed|launched)\b/i.test(text);

let score = 48;
score += presentSkills.length * 4;
score += hasNumbers ? 8 : 0;
score += hasEducation ? 6 : 0;
score += hasActionWords ? 8 : 0;
score += text.length > 1200 ? 6 : 0;
score -= missingSkills.length > 10 ? 4 : 0;
score = Math.max(35, Math.min(98, score));

const recommendations = [];
if (!hasNumbers) recommendations.push('Add measurable outcomes for each role with numbers or percentages.');
if (!hasActionWords) recommendations.push('Use stronger action verbs to describe impact.');
if (!hasEducation) recommendations.push('Include your education section clearly.');
if (presentSkills.length < 5) recommendations.push('Mention more role-relevant keywords and tools from your target job.');
if (text.length < 1500) recommendations.push('Expand bullet points so hiring systems can understand your experience better.');

const experienceMatch = text.match(/(\b\d+\+?\s+years?\b|\bfrom\s+\d{4}\s+to\s+\d{4}\b|\b20\d{2}\s*[-–]\s*20\d{2}\b)/gi) ?? [];
const educationMatch = text.match(/\b(bachelor|master|phd|b\.tech|m\.tech|university|college)\b/gi) ?? [];

return [
  {
    json: {
      success: true,
      executionId: body.executionId,
      agentId: body.agentId,
      result: {
        atsScore: score,
        skills: presentSkills.slice(0, 12),
        missingSkills: missingSkills.slice(0, 12),
        experience: experienceMatch.slice(0, 8),
        education: educationMatch.slice(0, 8),
        recommendations: recommendations.length ? recommendations : ['Resume looks solid. Tailor it to the target job title.'],
        summary: `Resume parsed successfully. ${presentSkills.length} ATS keywords detected.`,
        fileName,
        fileType,
      },
      usage: {
        model: 'n8n-local-heuristic',
        tokens: 0,
      },
      metadata: {
        analysisType: 'resume-analyzer',
        extractedCharacters: text.length,
        resumeFileName: fileName,
        resumeFileType: fileType,
      },
    },
  },
];
